/// <summary>
/// Initializes the class.
/// </summary>
protected void initSourceTable()
{
    next initSourceTable();

    this.metCreateStorelineCharge();

}

private void metCreateStorelineCharge()
{
    METSalesTable   metSalesTable;
    AmountCur       calculatedSalesTotal, customInvoiceTotal, differenceAmount;
    ttsbegin;

    if (salesTable.RecId)
    {
        select firstonly InvoiceTotal,OrderProcessingStatus
          from metSalesTable
              where  metSalesTable.SalesTable == salesTable.RecId;

        // Only compute the expensive total when external-total validation actually needs it.
        if (metSalesTable.OrderProcessingStatus == METSalesOrderProcessingStatus::ReadyForInvoicing
              && METSalesOrderTypes::find(salesTable.METSalesOrderType).ExternalTotalInvoiceValidation)
        {
            calculatedSalesTotal = SalesTotals::construct(salesTable).totalAmount();   // only when needed
            customInvoiceTotal   = metSalesTable.InvoiceTotal;
            differenceAmount     = customInvoiceTotal - calculatedSalesTotal;

            if (differenceAmount != 0)
            {
                this.addAdjustmentMarkup(differenceAmount, salesTable);
            }
        }

        this.updateExcludeFromDWOnSOLines(salesTable.SalesId);
    }
    ttscommit;
}

/// <summary>
/// Updates the ExcludeFromDualWrite flag to Yes on all METSalesLine records linked to the specified SalesParmTable
/// where the associated sales line is marked as an event order.
/// </summary>
/// <param name="_salesParmTable">The SalesParmTable buffer containing the sales parameter lines to process.</param>
public void updateExcludeFromDWOnSOLines(SalesId _salesId)
{
    SalesParmTable      salesParmTable;
    SalesParmLine       salesParmLine;
    METSalesLine        metSalesLine;

    select firstonly salesParmTable
    where salesParmTable.ParmId == parmId
        && salesParmTable.SalesId == _salesId;

    while select salesParmLine
        where salesParmLine.ParmId == salesParmTable.ParmId
            && salesParmLine.TableRefId == salesParmTable.TableRefId
        join metSalesLine
        where metSalesLine.SalesLine == salesParmLine.SalesLineRecId
            && metSalesLine.EventOrder == NoYes::Yes
    {
        metSalesLine.selectForUpdate(true);
        metSalesLine.ExcludeFromDualWrite = NoYes::Yes;
        metSalesLine.doUpdate();
    }
}

/// <summary>
/// Creates and inserts a non-taxable MarkupTrans record linked to the SalesTable
///</summary>
/// <param name = "_amount">The value required to meet the custom target total</param>
/// <param name = "_salesTable">salestable buffer</param>
private void addAdjustmentMarkup(real _amount, SalesTable _salesTable)
{
    MarkupTrans     markupTrans;
    CustParameters  custParameters = custParameters::find();

    //Inserting line in MarkUpTrans Table
    markupTrans.initValue();
    markupTrans.initFromSalesTable(_salesTable);
    markupTrans.initFromMarkupTable(MarkupTable::find(MarkupModuleType::Cust, custParameters.METInvTotalAdjChargeCode));
    markupTrans.LineNum        = MarkupTrans::lastLineNum(markupTrans.TransTableId, markupTrans.TransRecId) + 1;

    //Assigning the difference amount in markupTrans table and Ignoring the tax
    markupTrans.Value           = _amount;
    markupTrans.TaxGroup        = "";
    markupTrans.TaxItemGroup    = "";
    markupTrans.insert();
}

/// <summary>
///   Gets a journal and a voucher number.
/// </summary>
/// <returns>
///   A <c>Container</c> with a journal and voucher number.
/// </returns>
protected container getNumAndVoucher()
{
    METSalesTable       metSalesTable =  METSalesTable::findByRefRecId(salesTable.RecId);
    METSalesOrderTypes  metSalesOrderTypes = METSalesOrderTypes::find(salesTable.METSalesOrderType);

    next getNumAndVoucher();

    if (salesTable.SalesType == SalesType::Sales
            && strLen(metSalesTable.InvoiceNumber) > 0
            && metSalesOrderTypes.ExternalInvoiceNumber == NoYes::Yes)
    {
        journalNumber = metSalesTable.InvoiceNumber;
    }

    return [journalNumber, voucher];
}
